#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,bool(c)))
cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs')
config=text('crates/sparkbridge-config/src/lib.rs'); policy=text('crates/sparkbridge-policy/src/lib.rs'); secrets=text('crates/sparkbridge-secrets/src/lib.rs'); audit=text('crates/sparkbridge-audit/src/lib.rs')
server=text('apps/sparkbridge-server/src/main.rs'); store=text('apps/sparkbridge-server/src/store.rs'); executor=text('apps/sparkbridge-executor/src/main.rs'); execution=text('crates/sparkbridge-execution/src/lib.rs'); agent=text('apps/sparkbridge-server/src/agent_runtime.rs'); agentcore=text('crates/sparkbridge-agent/src/lib.rs'); task=text('crates/sparkbridge-task/src/lib.rs'); cli=text('apps/sparkbridge-cli/src/main.rs')
readme=text('README.md'); security=text('SECURITY.md'); guide=text('docs/POLICY_SECRETS.md'); user=text('docs/USER_MANUAL.md'); install=text('docs/INSTALLATION_GUIDE.md')
check('workspace version 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('schema is v9','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('policy/secrets/audit crates are workspace members',all(x in cargo for x in ['crates/sparkbridge-policy','crates/sparkbridge-secrets','crates/sparkbridge-audit']))
check('iteration 9 features negotiate','ITERATION_9_POLICY' in core and all(x in core for x in ['PolicyEngine','ApprovalWorkflow','SecretBroker','DataBoundaries','TamperEvidentAudit','NetworkSandbox']))
check('data classification enum exists',all(x in protocol for x in ['DataClassification','Public','Private','Confidential','Restricted']))
check('provider boundary enum exists',all(x in protocol for x in ['InferenceDataBoundary','LocalOnly','PrivateRemote','PublicCloud']))
check('permissions include policy/secrets',all(x in protocol for x in ['UseSecret','ManagePolicy','Promote','Approve','Execute','CandidateCreate']))
check('principal records are durable protocol objects','pub struct PrincipalRecord' in protocol and 'PrincipalKind' in protocol)
check('workspace policy has ACL secret allowlist approval list',all(x in protocol for x in ['allowed_principals','allowed_secret_refs','require_approval_for']))
check('policy decisions are allow ask deny',all(x in protocol for x in ['PolicyDecision','Allow','Ask','Deny']))
check('action has awaiting approval status','AwaitingApproval' in protocol and 'awaiting_approval' in store)
check('approval records expire','ApprovalStatus' in protocol and 'Expired' in protocol and 'expire_approvals' in store)
check('principals workspace policies approvals audit persist in SQLite',all(x in store for x in ['CREATE TABLE IF NOT EXISTS principals','CREATE TABLE IF NOT EXISTS workspace_policies','CREATE TABLE IF NOT EXISTS approvals','CREATE TABLE IF NOT EXISTS audit_events']))
check('local admin is seeded','seed_default_principal' in store and 'local-admin' in store and 'Permission::ManagePolicy' in store)
check('empty ACL is not public','policy.allowed_principals.is_empty()' in policy and 'principal.principal_id != "local-admin"' in policy)
check('disabled principal denies','!principal.enabled' in policy)
check('workspace approval requirements are honored','require_approval_for' in policy and 'PolicyDecision::Ask' in policy)
check('secret use needs permission','Permission::UseSecret' in policy and 'not authorized to use secrets' in policy)
check('secret refs must be explicitly workspace allowed','allowed_secret_refs.is_empty()' in policy and 'not explicitly allowed' in policy)
check('secret-bearing actions require approval','action requests one or more secret injections' in policy and 'PolicyDecision::Ask' in policy)
check('side effect actions require approval',all(x in policy for x in ['WorkspaceMutation','ExternalSideEffect','PrivilegedSideEffect']))
check('confidential unrestricted network escalates to ask','DataClassification::Confidential' in policy and 'unrestricted network access' in policy)
check('task creation checks candidate permission','Permission::CandidateCreate' in server and 'not authorized to create candidates' in server)
check('task runtime reauthorizes read each turn','Permission::Read' in agent and 'no longer has read access' in agent)
check('classification boundary checked at task create','classification_allows_boundary' in server and 'task data may not be sent' in server)
check('classification boundary rechecked before inference','classification_allows_boundary' in agent and 'data-boundary policy blocks' in agent)
check('server config exposes boundary and scan controls','inference_data_boundary' in config and 'context_secret_scan_enabled' in config and 'approval_ttl_seconds' in config)
check('workspace classification defaults are configurable','workspace_classifications' in config)
check('secret injection protocol contains reference only','pub struct SecretInjection' in protocol and 'pub reference: String' in protocol and 'pub env_name: String' in protocol)
check('action spec carries secret refs and declared hosts','secret_injections' in protocol and 'declared_hosts' in protocol)
check('task validation actions can carry secret refs','secret_injections' in task and 'declared_hosts' in task)
check('executor maps references to local env names','secret_env_bindings' in config and 'resolve_secret_injections' in executor)
check('executor advertises secret reference capability','format!("secret:{reference}")' in executor)
check('executor does not transmit local secret values','resolve_secret_injections' in secrets and 'std::env::var(local_name)' in secrets)
check('known injected values are scrubbed','redact_known_values' in execution and '[REDACTED:injected_secret]' in secrets)
check('generic process output secret scanner runs','scan_and_redact(&stdout)' in execution and 'scan_and_redact(&stderr)' in execution)
check('context secret scanner redacts before model','scan_and_redact(&content)' in agent and 'result.redacted' in agent)
check('candidate secret scanner rejects model output','candidate rejected: secret scanner' in agent and 'CandidateRejected' in agent)
check('model prompt forbids secret reconstruction','Never emit, reconstruct, request, or write credentials' in agentcore)
check('secret scanner recognizes multiple common shapes',all(x in secrets for x in ['private_key','github_token','aws_access_key','bearer_token','password_assignment','connection_string_secret']))
check('Linux network-none capability is conditional','action_allow_linux_network_none' in config and 'network:none' in execution and 'bubblewrap' in execution)
check('Linux network none uses unshare-net','--unshare-net' in execution and 'bwrap' in execution)
check('unenforceable restricted modes are rejected','dependency_fetch/declared_hosts network policies are not yet enforceable' in execution)
check('actions are centrally policy evaluated','evaluate_action' in server and 'ActionStatus::AwaitingApproval' in server)
check('secret capability required for scheduling','format!("secret:{}", injection.reference)' in server)
check('approval endpoint requires approve permission','Permission::Approve' in server and 'not authorized to approve operations' in server)
check('live promotion authorization endpoint exists','promotion-authorization' in server and 'authorize_promotion' in server)
check('live promotion always needs explicit approval','live promotion requires explicit loopback approval' in server and 'if !request.dry_run' in server)
check('promotion approval is candidate/workspace/principal bound',all(x in server for x in ['approval.workspace_id != request.workspace_id','approval.principal_id != request.principal_id','approval.operation != expected_operation']))
check('audit envelope chains previous hashes','previous_hash' in audit and 'hash_envelope' in audit and 'canonical_json' in audit)
check('audit store verifies chain','verify_audit' in store and 'first_invalid_sequence' in protocol)
check('CLI exposes policy approvals audit','Command::Policy' in cli and 'Command::Approvals' in cli and 'Command::Audit' in cli)
check('policy admin routes remain admin surface','/api/v1/admin/principals' in server and '/api/v1/admin/workspace-policies' in server and '/api/v1/admin/approvals' in server and '/api/v1/admin/audit' in server)
check('manual and install guide preserve current release identity',all('v0.12.0' in x and '1.10' in x for x in [user,install]))
check('policy guide documents secret values stay executor local','Secret values remain at the executor' in guide and 'live candidate promotion always requires explicit approval' in guide)
check('security model includes v0.9 amendments','secret' in security.lower() and 'policy' in security.lower() and 'data' in security.lower())
check('README carries forward v0.9 policy layer','policy' in readme.lower() and 'secret' in readme.lower() and 'data' in readme.lower())
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
    print(f'\n{len(failed)} policy/security invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nPolicy + Secrets audit passed: {len(checks)} invariants')
